#include <vector>
#include <algorithm>

class Solution {
public:
    double separateSquares(std::vector<std::vector<int>>& squares) {
        double total_area = 0;
        double low = 1e18;
        double high = 0;

        for (const auto& sq : squares) {
            double y = sq[1];
            double l = sq[2];
            total_area += l * l;
            low = std::min(low, y);
            high = std::max(high, y + l);
        }

        double target = total_area / 2.0;
        for (int iter = 0; iter < 60; ++iter) {
            double mid = (low + high) / 2.0;
            double area_below = 0;
            for (const auto& sq : squares) {
                double y = sq[1];
                double l = sq[2];
                if (mid >= y + l) {
                    area_below += l * l;
                } else if (mid > y) {
                    area_below += l * (mid - y);
                }
            }
            if (area_below < target) {
                low = mid;
            } else {
                high = mid;
            }
        }
        return high;
    }
};

