var separateSquares = function(squares) {
    let totalArea = 0;
    let low = Infinity;
    let high = -Infinity;

    for (let i = 0; i < squares.length; i++) {
        const y = squares[i][1];
        const l = squares[i][2];
        totalArea += l * l;
        if (y < low) low = y;
        if (y + l > high) high = y + l;
    }

    const target = totalArea / 2.0;
    for (let iter = 0; iter < 60; iter++) {
        const mid = (low + high) / 2.0;
        let areaBelow = 0;
        for (let i = 0; i < squares.length; i++) {
            const y = squares[i][1];
            const l = squares[i][2];
            if (mid >= y + l) {
                areaBelow += l * l;
            } else if (mid > y) {
                areaBelow += l * (mid - y);
            }
        }
        if (areaBelow < target) {
            low = mid;
        } else {
            high = mid;
        }
    }
    return high;
};
